function authorNames(author) {
  if (!author) {
    return "";
  }

  const authors = Array.isArray(author) ? author : [author];

  return authors
    .map((person) =&gt; {
      if (typeof person === "string") {
        return person;
      }

      if (person && person.name) {
        return person.name;
      }

      if (person && person.given && person.family) {
        return `${person.given} ${person.family}`;
      }

      return "";
    })
    .filter(Boolean)
    .join(", ");
}
